1	"use client";
2	
3	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
7	import BuildingOverlay from "./BuildingOverlay";
8	import BuildRating from "./BuildRating";
9	import BuildInterrupted, { type Interruption } from "./BuildInterrupted";
10	import CommandPalette, { type CommandGroup } from "./CommandPalette";
11	import PreviewFrame, { DEVICES, type DeviceId } from "./PreviewFrame";
12	
13	type Message = { role: string; content: string };
14	type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };
15	
16	type Props = {
17	  projectId: string;
18	  projectName: string;
19	  slug: string;
20	  published: boolean;
21	  initialFiles: Record<string, string>;
22	  initialMessages: Message[];
23	  initialBalance: number;
24	  /** This user's measured average credits per build — see lib/credits.ts. */
25	  avgBuildCredits: number;
26	};
27	
28	const SITES_BASE = process.env.NEXT_PUBLIC_SITES_BASE ?? "kodely.site";
29	
30	// Mirrors the publish route's own Host-based derivation (see the comment
31	// there) so the header's "live site" link always matches what publish
32	// actually returned, on staging or prod, without hardcoding either.
33	const FOCUS_RING =
34	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
35	
36	// Thrown for an `error` event the SERVER sent us, so the catch below can tell
37	// "the build failed and told us why" apart from "the pipe broke" — which are
38	// completely different messages to the user. Anything else that surfaces after
39	// streaming has begun is transport, not the build.
40	class BuildServerError extends Error {}
41	
42	// The platform never changes under us, so there is nothing to subscribe to —
43	// but reading navigator during render would make the server and client
44	// disagree. useSyncExternalStore with a server snapshot is the sanctioned way
45	// to say "assume Ctrl on the server, correct it on the client", and unlike a
46	// setState-in-effect it cannot produce a hydration mismatch on the way.
47	const NO_SUBSCRIBE = () => () => {};
48	const isMacClient = () => /Mac|iPhone|iPad|iPod/.test(navigator.userAgent);
49	const isMacServer = () => false;
50	
51	function liveSiteUrl(slug: string): string {
52	  if (typeof window === "undefined") return `https://${slug}.${SITES_BASE}`;
53	  const host = window.location.host;
54	  return host.includes("staging")
55	    ? `${window.location.origin}/api/site/${slug}`
56	    : `https://${slug}.${SITES_BASE}`;
57	}
58	
59	export default function Editor(props: Props) {
60	  const [messages, setMessages] = useState<Message[]>(props.initialMessages);
61	  const [files, setFiles] = useState(props.initialFiles);
62	  const [prompt, setPrompt] = useState("");
63	  const [busy, setBusy] = useState(false);
64	  const [status, setStatus] = useState<string | null>(null);
65	  const [error, setError] = useState<string | null>(null);
66	  const [balance, setBalance] = useState(props.initialBalance);
67	  // The build just finished in THIS session, so it can be rated. Deliberately
68	  // not restored on reload: rating a build you last saw yesterday is guesswork.
69	  const [lastBuildId, setLastBuildId] = useState<string | null>(null);
70	  const [previewNonce, setPreviewNonce] = useState(0);
71	  const [published, setPublished] = useState(props.published);
72	  const [publishing, setPublishing] = useState(false);
73	  const [view, setView] = useState<"preview" | "code" | "history">("preview");
74	  const [builds, setBuilds] = useState<BuildCheckpoint[] | null>(null);
75	  const [restoring, setRestoring] = useState<string | null>(null);
76	  const [activeFile, setActiveFile] = useState<string | null>(null);
77	  const [downloading, setDownloading] = useState(false);
78	  const [enhancing, setEnhancing] = useState(false);
79	  // The prompt as typed, held only while an expanded spec sits in the box.
80	  // Doubles as the "we're showing a spec" flag and as what Revert restores.
81	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
82	  // A build that ended without finishing — stopped on purpose, or the stream
83	  // died. Not `error`: nothing went wrong, so it must not read like a failure.
84	  const [interruption, setInterruption] = useState<Interruption | null>(null);
85	  // Did we actually SEE the build write anything before it was interrupted?
86	  // Rendered state because BuildInterrupted's copy depends on it — see the
87	  // engine note at the top of that file for why it cannot be assumed.
88	  const [wroteFiles, setWroteFiles] = useState(false);
89	  const [device, setDevice] = useState<DeviceId>("desktop");
90	  const [paletteOpen, setPaletteOpen] = useState(false);
91	  // Abort has been requested but the stream hasn't unwound yet. Rendered
92	  // state, not just the ref below, so the button can actually go dead.
93	  const [stopping, setStopping] = useState(false);
94	  const streamingReply = useRef("");
95	  // Aborting this is what the Stop button does; the route's stream cancel()
96	  // sees the disconnect and aborts the model call on the server side.
97	  const abortRef = useRef<AbortController | null>(null);
98	  const stopRequested = useRef(false);
99	  const promptRef = useRef<HTMLTextAreaElement>(null);
100	  const paletteTriggerRef = useRef<HTMLButtonElement>(null);
101	  // What had focus when the palette opened, so closing can hand it back.
102	  const paletteReturn = useRef<HTMLElement | null>(null);
103	  const router = useRouter();
104	
105	  const modKey = useSyncExternalStore(NO_SUBSCRIBE, isMacClient, isMacServer) ? "⌘" : "Ctrl";
106	
107	  async function refreshFiles() {
108	    const res = await fetch(`/api/projects/${props.projectId}`);
109	    const body = await res.json();
110	    setFiles(
111	      Object.fromEntries(
112	        (body.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
113	      ),
114	    );
115	    setPreviewNonce((n) => n + 1);
116	  }
117	
118	  async function openHistory() {
119	    setView("history");
120	    const res = await fetch(`/api/projects/${props.projectId}/builds`);
121	    const body = await res.json();
122	    setBuilds(body.builds ?? []);
123	  }
124	
125	  async function restore(buildId: string) {
126	    if (!confirm("Restore this checkpoint? Your current draft will be replaced.")) return;
127	    setRestoring(buildId);
128	    setError(null);
129	    try {
130	      const res = await fetch(`/api/projects/${props.projectId}/builds/${buildId}/restore`, {
131	        method: "POST",
132	      });
133	      const body = await res.json();
134	      if (!res.ok) throw new Error(body?.error ?? "Restore failed.");
135	      const res2 = await fetch(`/api/projects/${props.projectId}`);
136	      const body2 = await res2.json();
137	      const nextFiles: Record<string, string> = Object.fromEntries(
138	        (body2.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
139	      );
140	      setFiles(nextFiles);
141	      setPreviewNonce((n) => n + 1);
142	      setView("preview");
143	    } catch (err) {
144	      setError(err instanceof Error ? err.message : "Restore failed.");
145	    } finally {
146	      setRestoring(null);
147	    }
148	  }
149	
150	  // The foundation means source files are never empty — "first build" means
151	  // no chat history yet, matching the same signal the generate route uses.
152	  const isFirstBuild = messages.length === 0;
153	
154	  // If the visitor typed a prompt on the homepage before hitting the auth
155	  // wall, that prompt survives login/signup in sessionStorage — fire it
156	  // automatically the moment they land in their new project, instead of
157	  // making them retype what they already told us.
158	  useEffect(() => {
159	    if (!isFirstBuild) return;
160	    let pending: string | null = null;
161	    let pendingImage: string | null = null;
162	    try {
163	      pending = sessionStorage.getItem(PENDING_PROMPT_KEY);
164	      pendingImage = sessionStorage.getItem(PENDING_PROMPT_IMAGE_KEY);
165	    } catch {}
166	    if (!pending) return;
167	    try {
168	      sessionStorage.removeItem(PENDING_PROMPT_KEY);
169	      sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
170	    } catch {}
171	    send(pending, pendingImage ?? undefined);
172	    // Runs once on mount only — send() is intentionally not a dependency.
173	    // eslint-disable-next-line react-hooks/exhaustive-deps
174	  }, []);
175	
176	  async function send(overrideText?: string, image?: string) {
177	    const text = (overrideText ?? prompt).trim();
178	    if (!text || busy) return;
179	    if (balance <= 0) {
180	      setError("You're out of credits. Top up to keep building.");
181	      return;
182	    }
183	
184	    setBusy(true);
185	    setError(null);
186	    setInterruption(null);
187	    setWroteFiles(false);
188	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
189	    setMessages((m) => [...m, { role: "user", content: text }]);
190	    setPrompt("");
191	    setEnhancedFrom(null);
192	    streamingReply.current = "";
193	    stopRequested.current = false;
194	    const controller = new AbortController();
195	    abortRef.current = controller;
196	
197	    // Set once the first byte of the stream lands. After that point any
198	    // failure is the connection, not the request — which is what lets us tell
199	    // "couldn't start" apart from "died halfway".
200	    let streamStarted = false;
201	    // A `done` or `error` event. The route always sends one of them unless it
202	    // saw the client go away, so a stream that closes without either IS the
203	    // signature of a dropped connection.
204	    let sawTerminal = false;
205	    let touchedFiles = false;
206	
207	    try {
208	      const res = await fetch("/api/generate", {
209	        method: "POST",
210	        headers: { "Content-Type": "application/json" },
211	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
212	        signal: controller.signal,
213	      });
214	
215	      if (!res.ok || !res.body) {
216	        const body = await res.json().catch(() => ({}));
217	        throw new Error(body?.error ?? "The build failed to start.");
218	      }
219	
220	      const reader = res.body.getReader();
221	      const decoder = new TextDecoder();
222	      let buffer = "";
223	
224	      while (true) {
225	        const { done, value } = await reader.read();
226	        if (done) break;
227	        streamStarted = true;
228	        buffer += decoder.decode(value, { stream: true });
229	
230	        const parts = buffer.split("\n\n");
231	        buffer = parts.pop() ?? "";
232	
233	        for (const part of parts) {
234	          if (!part.startsWith("data: ")) continue;
235	          const event = JSON.parse(part.slice(6));
236	
237	          if (event.type === "text") {
238	            streamingReply.current += event.text;
239	          } else if (event.type === "progress" || event.type === "status") {
240	            // Both drive the same line. `progress` comes from a real tool call,
241	            // `status` from a phase the route knows about (a repair pass).
242	            setStatus(event.text);
243	          } else if (event.type === "file") {
244	            // On the SDK engine these all arrive at once after the build, so
245	            // they are a completion signal, not live progress — the progress
246	            // line above is what the user actually watches. On the `api`
247	            // engine they arrive one per write, which is what makes them
248	            // usable as evidence that a stopped build left files behind.
249	            touchedFiles = true;
250	            setWroteFiles(true);
251	          } else if (event.type === "done") {
252	            sawTerminal = true;
253	            setBalance(event.remaining);
254	            setStatus(null);
255	            setLastBuildId(event.buildId ?? null);
256	          } else if (event.type === "error") {
257	            sawTerminal = true;
258	            throw new BuildServerError(event.message);
259	          }
260	        }
261	      }
262	
263	      if (!sawTerminal) {
264	        // The pipe closed mid-build. Nothing was thrown, no error arrived —
265	        // this is exactly the silent stop the user used to be left staring at.
266	        setInterruption("connection-lost");
267	      } else if (streamingReply.current.trim()) {
268	        // Only on a build that actually completed: the route persists the
269	        // assistant reply in the success branch alone, so showing it after an
270	        // interruption would put a message on screen that a reload deletes.
271	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
272	      }
273	      // Deliberately swallowed. This runs AFTER the stream has closed cleanly,
274	      // so the build is already over and its outcome already decided — letting
275	      // a failed re-fetch fall into the catch below would report a finished
276	      // build as a lost connection, which is the one thing that block must
277	      // never say wrongly. A stale file list is a reload away; a false
278	      // "connection lost" sends the user hunting for a problem that isn't
279	      // there.
280	      if (touchedFiles) await refreshFiles().catch(() => {});
281	    } catch (err) {
282	      if (stopRequested.current) {
283	        setInterruption("stopped");
284	        // Files the agent wrote before the abort are already committed to the
285	        // draft source, so pull them in — the Code view should show what is
286	        // really there, half-finished or not.
287	        if (touchedFiles) await refreshFiles().catch(() => {});
288	      } else if (err instanceof BuildServerError) {
289	        setError(err.message);
290	      } else if (streamStarted) {
291	        setInterruption("connection-lost");
292	      } else {
293	        setError(err instanceof Error ? err.message : "Something went wrong.");
294	      }
295	    } finally {
296	      abortRef.current = null;
297	      stopRequested.current = false;
298	      setStopping(false);
299	      setBusy(false);
300	      setStatus(null);
301	    }
302	  }
303	
304	  // Stop is a real cancel, not a UI-only one: aborting the fetch closes the
305	  // response body, which fires cancel() on the route's ReadableStream, which
306	  // aborts the model request server-side. The build row is then written FAILED
307	  // with creditsCharged: 0 — nothing is billed. See BuildInterrupted.tsx.
308	  function stop() {
309	    if (!busy || stopping || !abortRef.current) return;
310	    stopRequested.current = true;
311	    setStopping(true);
312	    setStatus("Stopping…");
313	    abortRef.current.abort();
314	  }
315	
316	  // Goes through fetch rather than a plain download link so a failure lands in
317	  // the same error strip as everything else here, instead of silently saving
318	  // the JSON error body as "slug.zip".
319	  async function downloadZip() {
320	    setDownloading(true);
321	    setError(null);
322	    try {
323	      const res = await fetch(`/api/projects/${props.projectId}/export`);
324	      if (!res.ok) {
325	        const body = await res.json().catch(() => ({}));
326	        throw new Error(body?.error ?? "Download failed.");
327	      }
328	      const url = URL.createObjectURL(await res.blob());
329	      const link = document.createElement("a");
330	      link.href = url;
331	      link.download = `${props.slug}.zip`;
332	      link.click();
333	      // The click hands the blob off asynchronously, so revoking in the same
334	      // tick can cancel the download in some browsers. Next tick is enough,
335	      // and skipping the revoke entirely would pin the archive in memory for
336	      // the life of the tab.
337	      setTimeout(() => URL.revokeObjectURL(url), 0);
338	    } catch (err) {
339	      setError(err instanceof Error ? err.message : "Download failed.");
340	    } finally {
341	      setDownloading(false);
342	    }
343	  }
344	
345	  // Expand the draft prompt into a spec the user can read and edit before
346	  // spending anything. The result lands in the prompt box itself — it is
347	  // already editable, and it is already what the build button reads — so
348	  // "accept" is just pressing Build, "edit" is typing, "discard" is Revert.
349	  async function enhance() {
350	    const text = prompt.trim();
351	    if (!text || enhancing || busy) return;
352	
353	    setEnhancing(true);
354	    setError(null);
355	    try {
356	      const res = await fetch("/api/enhance", {
357	        method: "POST",
358	        headers: { "Content-Type": "application/json" },
359	        // Always the ORIGINAL one-liner, never a spec we already produced —
360	        // re-expanding an expansion compounds invention instead of adding
361	        // detail.
362	        body: JSON.stringify({ prompt: enhancedFrom ?? text }),
363	      });
364	      const body = await res.json().catch(() => ({}));
365	      if (!res.ok || !body?.spec) throw new Error(body?.error ?? "Couldn't expand that.");
366	      setEnhancedFrom(enhancedFrom ?? text);
367	      setPrompt(body.spec);
368	    } catch (err) {
369	      // Nothing is lost: the typed prompt is still in the box and Build was
370	      // never disabled by this. Enhance is a convenience, never a gate.
371	      setError(err instanceof Error ? err.message : "Couldn't expand that.");
372	    } finally {
373	      setEnhancing(false);
374	    }
375	  }
