385	  // disambiguation of a key the box already owns (⌘⏎ builds even when Enter
386	  // has been handed over to the spec editor). Anything more inventive would
387	  // be a shortcut nobody discovers and everybody triggers by accident.
388	  // Bound only while the palette is CLOSED. While it is open the dialog owns
389	  // the keyboard outright — that is what makes the focus trap and the Escape
390	  // handling airtight, and it saves reading a "is it open" ref during render.
391	  useEffect(() => {
392	    if (paletteOpen) return;
393	    function onKeyDown(e: KeyboardEvent) {
394	      const mod = e.metaKey || e.ctrlKey;
395	      const openWith = (opener: HTMLElement | null) => {
396	        paletteReturn.current = opener;
397	        setPaletteOpen(true);
398	      };
399	      const active = document.activeElement;
400	      const focused = active instanceof HTMLElement && active !== document.body ? active : null;
