"use client";

// Plan-before-spend: what a build is likely to cost, shown BEFORE the button
// that spends it. Sits directly above Build/Apply and is wired to that button
// with aria-describedby, so the estimate is read out when the button takes
// focus — no second live region (two of those in this file is exactly how the
// progress line ended up being announced twice).
//
// ── What this must never do ───────────────────────────────────────────────
// Present a precise number. estimateCredits() in lib/credits.ts is explicit
// that its range comes from TWO measured builds, 144 and 472 credits — a 3x
// spread that the function's own comment calls "not a distribution". Averaging
// those into "about 300 credits" would be inventing a prediction out of two
// samples, on the one product surface whose entire promise is no bill shock.
// So the global figure is only ever shown as the bracket it is.
//
// Once the user HAS history, their own measured average is a better answer
// than our bracket, and it replaces it — but only when there is really a
// measurement behind it. averageBuildCredits() silently falls back to a global
// constant for a user with no charged builds, so `measuredBuilds` is what
// decides whether we are allowed to call it "your" average. Same gate as the
// "Your average build" tile in app/dashboard/billing/page.tsx, and the same
// reason.

export type CreditRange = { low: number; high: number };

export default function CostEstimate({
  id,
  kind,
  range,
  balance,
  avgBuildCredits,
  measuredBuilds,
}: {
  /** Referenced by the Build button's aria-describedby. */
  id: string;
  kind: "create" | "edit";
  /** estimateCredits(kind) — computed on the server, see page.tsx. */
  range: CreditRange;
  balance: number;
  /** This user's measured average. Only trustworthy when measuredBuilds > 0. */
  avgBuildCredits: number;
  /** Successful, charged builds this user has. 0 means we have measured nothing. */
  measuredBuilds: number;
}) {
  const measured = measuredBuilds > 0;

  // What we compare the balance against. With history that is the user's own
  // average; without it, the TOP of the bracket — warning against the bottom
  // of a 120–550 range would be a warning that never fires when it matters.
  const reference = measured ? avgBuildCredits : range.high;
  const short = balance > 0 && balance < reference;
  const empty = balance <= 0;

  return (
    <div
      id={id}
      className="mb-2 rounded-md border border-black/10 px-2.5 py-2 text-xs dark:border-white/10"
    >
      <div className="flex items-baseline justify-between gap-2">
        <span className="font-medium text-black/70 dark:text-white/70">
          {kind === "create" ? "Likely cost of this build" : "Likely cost of this change"}
        </span>
        <span className="shrink-0 tabular-nums text-black/60 dark:text-white/60">
          {measured ? `~${avgBuildCredits} credits` : `${range.low}–${range.high} credits`}
        </span>
      </div>

      <p className="mt-1 text-black/45 dark:text-white/45">
        {measured
          ? `Averaged from your own builds (${measuredBuilds} charged so far). An average, not a quote — this one can land either side of it.`
          : "A deliberately wide bracket from the handful of builds we have measured, not a prediction. You are charged for what the build actually uses."}
      </p>

      {(short || empty) && (
        <p
          className={`mt-1.5 ${
            empty ? "text-red-600 dark:text-red-400" : "text-amber-600 dark:text-amber-500"
          }`}
        >
          {empty ? (
            <>You have no credits left, so this build won&rsquo;t start.</>
          ) : (
            <>
              You have {balance} credits — {measured ? "less than your average build" : "less than the top of that range"}.
              {" "}
              {/* Verified against app/api/generate/route.ts: the only pre-flight
                  gate is balance <= 0 (plus the spend cap). Nothing stops a
                  build partway for cost, and chargeForBuild writes the real
                  amount even when it takes the balance negative — so promising
                  a mid-build cutoff here would be inventing engine behaviour. */}
              A build that costs more than you have still finishes and is charged in full; it&rsquo;s the
              next one that won&rsquo;t start.
            </>
          )}
        </p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// Search & social metadata, visible and editable WITHOUT paying for a build.
//
// Where these values actually live: there is no seo column anywhere. The head
// of the project's own `index.html` IS the storage (see lib/foundation.ts for
// the scaffold the agent is handed, and the head-writing instructions in the
// SYSTEM prompt in lib/agent.ts). So this panel reads the draft SOURCE
// index.html the editor already holds, and a save has to rewrite that same
// file — which is why the endpoint contract below is what it is.
//
// Three separate copies of index.html exist per project, and they are NOT
// interchangeable:
//   draft  + kind "source"  — what the agent edits and what this panel reads.
//   draft  + kind "build"   — the compiled output the in-editor preview serves.
//   published + kind "build" — what visitors get; only the publish route writes it.
// A save must touch the first two and must never touch the third: going live
// stays an explicit act. That is stated again on the endpoint contract below.
//
// What lib/site-seo.ts does on top of this, at serve time and for published
// sites only, is a BACKSTOP for gaps — it never overrides a value that is
// present. The "What visitors see" column mirrors those rules exactly so the
// panel can never show something different from what is actually served.

/** lib/site-seo.ts's own placeholder constant. Not exported there; mirrored. */
const PLACEHOLDER_TITLE = "Kodely Site";

// Guidance, not limits. Straight out of the SYSTEM prompt the builder is given
// (lib/agent.ts): title under ~60 characters, description ~150. Going over is
// allowed — search engines truncate, they do not reject — so this only ever
// changes a colour and a number, never disables the save.
const TITLE_TARGET = 60;
const DESC_TARGET = 150;

const FOCUS_RING =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";

const FIELD =
  "w-full rounded-lg border border-black/15 bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40";

export type SeoTags = {
  title: string;
  description: string;
  ogTitle: string;
  ogDescription: string;
  /** Read-only here: it is an asset reference, not copy. */
  ogImage: string;
};

const EMPTY: SeoTags = { title: "", description: "", ogTitle: "", ogDescription: "", ogImage: "" };

/**
 * Read the head with the browser's own HTML parser rather than regexes:
 * attribute order, quoting style and entities (&amp;, &#39;) are all things
 * the builder writes freely and all things a regex would show back to the
 * user raw. This runs client-side only — the panel is never server-rendered,
 * since it mounts only once the user switches to this view.
 */
function parseHead(html: string | undefined): SeoTags {
  if (!html || typeof DOMParser === "undefined") return EMPTY;
  const doc = new DOMParser().parseFromString(html, "text/html");
  const content = (selector: string) =>
    doc.querySelector(selector)?.getAttribute("content")?.trim() ?? "";
  return {
    title: doc.querySelector("title")?.textContent?.trim() ?? "",
    description: content('meta[name="description"]'),
    ogTitle: content('meta[property="og:title"]'),
    ogDescription: content('meta[property="og:description"]'),
    ogImage: content('meta[property="og:image"]'),
  };
}

/**
 * What a visitor and a crawler actually get for a PUBLISHED site, gaps
 * included. Mirrors applySeo() in lib/site-seo.ts line for line.
 *
 * One rule here is easy to get wrong and is deliberately preserved: an empty
 * og:description does NOT inherit the page description. applySeo computes one
 * generic string from the title and uses it for both, so leaving og:description
 * blank while writing a real description gets you the generic line in every
 * link preview. Showing that plainly is the point of this column.
 */
function servedValues(tags: SeoTags, projectName: string) {
  const title =
    !tags.title || tags.title === PLACEHOLDER_TITLE ? projectName : tags.title;
  const generated = `${title} — built with Kodely.`;
  return {
    title,
    titleIsFallback: !tags.title || tags.title === PLACEHOLDER_TITLE,
    description: tags.description || generated,
    descriptionIsFallback: !tags.description,
    ogTitle: tags.ogTitle || title,
    ogTitleIsFallback: !tags.ogTitle,
    ogDescription: tags.ogDescription || generated,
    ogDescriptionIsFallback: !tags.ogDescription,
  };
}

function sameTags(a: SeoTags, b: SeoTags): boolean {
  return (
    a.title === b.title &&
    a.description === b.description &&
    a.ogTitle === b.ogTitle &&
    a.ogDescription === b.ogDescription
  );
}

export default function SeoPanel({
  projectId,
  projectName,
  published,
  liveUrl,
  html,
  onSaved,
}: {
  projectId: string;
  projectName: string;
  published: boolean;
  /** Public URL, when the site is live. Used for the canonical/og:url note. */
  liveUrl: string | null;
  /** Draft source index.html, straight from the editor's file map. */
  html: string | undefined;
  /** Re-read the project's files after a successful save. */
  onSaved: () => void | Promise<void>;
}) {
  // ── The endpoint this panel needs ───────────────────────────────────────
  // PUT /api/projects/<id>/seo does not exist yet, and creating routes was
  // out of scope for this change. Rather than ship a Save button that is
  // quietly guaranteed to fail, the panel asks the server once whether the
  // route is there and says so plainly if it isn't. When the route ships,
  // nothing here needs to change.
  const endpoint = `/api/projects/${projectId}/seo`;
  const [saveSupport, setSaveSupport] = useState<"checking" | "ready" | "missing">("checking");
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [savedAt, setSavedAt] = useState<number | null>(null);

  const current = useMemo(() => parseHead(html), [html]);
  const [draft, setDraft] = useState<SeoTags>(current);
  const baseline = useRef(current);

  // Adopt new file contents (a finished build, or our own save landing) only
  // when the user has nothing unsaved in the boxes. Silently replacing text
  // someone is halfway through typing is worse than showing a stale value.
  useEffect(() => {
    setDraft((d) => (sameTags(d, baseline.current) ? current : d));
    baseline.current = current;
  }, [current]);

  useEffect(() => {
    let cancelled = false;
    // OPTIONS: no side effects either way, and Next answers 405 for a route
    // that exists without this method versus 404 for no route at all.
    fetch(endpoint, { method: "OPTIONS" })
      .then((res) => {
        if (!cancelled) setSaveSupport(res.status === 404 ? "missing" : "ready");
      })
      .catch(() => {
        if (!cancelled) setSaveSupport("missing");
      });
    return () => {
      cancelled = true;
    };
  }, [endpoint]);

  const dirty = !sameTags(draft, current);
  const served = servedValues(draft, projectName);

  async function save() {
    if (saving || !dirty) return;
    setSaving(true);
    setSaveError(null);
    try {
      const res = await fetch(endpoint, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: draft.title,
          description: draft.description,
          ogTitle: draft.ogTitle,
          ogDescription: draft.ogDescription,
        }),
      });
      if (res.status === 404 || res.status === 405) {
        setSaveSupport("missing");
        throw new Error("Saving isn't wired up on the server yet.");
      }
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body?.error ?? "Couldn't save these.");
      setSavedAt(Date.now());
      await onSaved();
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : "Couldn't save these.");
    } finally {
      setSaving(false);
    }
  }

  const field = (
    key: "title" | "description" | "ogTitle" | "ogDescription",
    label: string,
    hint: string,
    target: number | null,
    multiline: boolean,
  ) => {
    const value = draft[key];
    const inputId = `kodely-seo-${key}`;
    const hintId = `${inputId}-hint`;
    const over = target !== null && value.length > target;
    return (
      <div>
        <div className="flex items-baseline justify-between gap-2">
          <label htmlFor={inputId} className="text-xs font-medium">
            {label}
          </label>
          {target !== null && (
            <span
              className={`shrink-0 text-xs tabular-nums ${
                over ? "text-amber-600 dark:text-amber-500" : "text-black/40 dark:text-white/40"
              }`}
            >
              {value.length}/{target}
            </span>
          )}
        </div>
        {multiline ? (
          <textarea
            id={inputId}
            value={value}
            rows={3}
            onChange={(e) => setDraft((d) => ({ ...d, [key]: e.target.value }))}
            aria-describedby={hintId}
            className={`mt-1 resize-none ${FIELD}`}
          />
        ) : (
          <input
            id={inputId}
            type="text"
            value={value}
            onChange={(e) => setDraft((d) => ({ ...d, [key]: e.target.value }))}
            aria-describedby={hintId}
            className={`mt-1 ${FIELD}`}
          />
        )}
        <p id={hintId} className="mt-1 text-xs text-black/40 dark:text-white/40">
          {hint}
          {target !== null && over && ` Over ~${target} characters, so search results will trim it.`}
        </p>
      </div>
    );
  };

  return (
    <div className="h-full overflow-y-auto p-4">
      <div className="mx-auto max-w-2xl">
        <h2 className="text-sm font-medium">Search &amp; social</h2>
        <p className="mt-1 text-xs text-black/50 dark:text-white/50">
          The tab title, the search-result snippet and the link preview, read from your{" "}
          <code className="rounded bg-black/5 px-1 py-0.5 dark:bg-white/10">index.html</code>. Editing
          them here changes them directly — no build, no credits. A later build can rewrite them
          again, since the builder writes the head too.
        </p>

        {html === undefined ? (
          <p className="mt-4 rounded-lg border border-black/10 px-3 py-2 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
            This project has no index.html yet, so there is nothing to edit.
          </p>
        ) : (
          <>
            <div className="mt-4 space-y-4">
              {field(
                "title",
                "Page title",
                "Shown in the browser tab and as the headline of a search result.",
                TITLE_TARGET,
                false,
              )}
              {field(
                "description",
                "Meta description",
                "The grey snippet under the headline in search results.",
                DESC_TARGET,
                true,
              )}
              {field(
                "ogTitle",
                "Share title (og:title)",
                "The bold line when someone pastes your link into a chat or a post.",
                TITLE_TARGET,
                false,
              )}
              {field(
                "ogDescription",
                "Share description (og:description)",
                "The smaller line under it. Left blank, it does NOT copy your meta description — a generic one is used instead.",
                DESC_TARGET,
                true,
              )}
            </div>

            <div className="mt-3 flex flex-wrap items-center gap-2">
              <button
                type="button"
                onClick={save}
                disabled={!dirty || saving || saveSupport !== "ready"}
                className={`rounded-lg bg-black px-3 py-2 text-sm font-medium text-white disabled:opacity-40 dark:bg-white dark:text-black ${FOCUS_RING}`}
              >
                {saving ? "Saving…" : "Save"}
              </button>
              <button
                type="button"
                onClick={() => setDraft(current)}
                disabled={!dirty || saving}
                className={`rounded-lg border border-black/15 px-3 py-2 text-sm disabled:opacity-40 dark:border-white/15 ${FOCUS_RING}`}
              >
                Reset
              </button>
              {/* One status region for this panel, and it never carries a
                  string that is announced anywhere else on the screen. */}
              <p role="status" className="text-xs text-black/50 dark:text-white/50">
                {saveError
                  ? ""
                  : savedAt !== null && !dirty
                    ? "Saved to your draft."
                    : dirty
                      ? "Unsaved changes."
                      : ""}
              </p>
            </div>

            {saveError && <p className="mt-2 text-xs text-red-600">{saveError}</p>}

            {saveSupport === "missing" && (
              // Deliberately concrete. "Saving is unavailable" tells a user
              // nothing; naming the missing route tells whoever has to fix it
              // exactly what is missing, and tells the user this is a gap in
              // Kodely rather than something they did wrong.
              <p className="mt-2 rounded-md border border-amber-500/40 px-2.5 py-2 text-xs text-amber-700 dark:text-amber-500">
                Saving isn&rsquo;t available yet — this build of Kodely has no{" "}
                <code>PUT {endpoint}</code> endpoint. You can still read and rehearse the values
                here; they will not persist.
              </p>
            )}

            <h3 className="mt-6 text-xs font-medium">What a visitor sees</h3>
            <p className="mt-1 text-xs text-black/40 dark:text-white/40">
              Anything you leave blank is filled in on the published site by Kodely&rsquo;s backstop,
              so a site is never served with an empty head. These are the values it would use.
            </p>
            <dl className="mt-2 divide-y divide-black/10 rounded-lg border border-black/10 text-xs dark:divide-white/10 dark:border-white/10">
              <Served label="Title" value={served.title} fallback={served.titleIsFallback} />
              <Served
                label="Description"
                value={served.description}
                fallback={served.descriptionIsFallback}
              />
              <Served label="og:title" value={served.ogTitle} fallback={served.ogTitleIsFallback} />
              <Served
                label="og:description"
                value={served.ogDescription}
                fallback={served.ogDescriptionIsFallback}
              />
              {current.ogImage && <Served label="og:image" value={current.ogImage} fallback={false} />}
            </dl>

            <h3 className="mt-6 text-xs font-medium">Handled for you</h3>
            <ul className="mt-2 space-y-1 text-xs text-black/50 dark:text-white/50">
              <li>
                <code>canonical</code> and <code>og:url</code> — set to{" "}
                {liveUrl ? <span className="break-all">{liveUrl}</span> : "your site's address"} when
                a page is served.
              </li>
              <li>
                <code>og:type</code> and <code>twitter:card</code> — filled in if the page has none.
              </li>
              <li>
                <code>og:image</code> — a relative path is rewritten to a full URL, because crawlers
                reject relative ones.
              </li>
              <li>
                <code>robots.txt</code> and <code>sitemap.xml</code> — generated for every published
                site from its own pages.
              </li>
            </ul>

            <p className="mt-4 text-xs text-black/40 dark:text-white/40">
              {published
                ? "Saving updates your draft and the preview. Your live site keeps its current tags until you republish."
                : "Saving updates your draft. These go live the first time you publish."}
            </p>
          </>
        )}
      </div>
    </div>
  );
}

function Served({
  label,
  value,
  fallback,
}: {
  label: string;
  value: string;
  fallback: boolean;
}) {
  return (
    <div className="flex flex-col gap-0.5 px-3 py-2 sm:flex-row sm:gap-3">
      <dt className="shrink-0 text-black/40 sm:w-28 dark:text-white/40">{label}</dt>
      <dd className="min-w-0 break-words">
        {value}
        {fallback && (
          <span className="ml-1.5 whitespace-nowrap rounded border border-black/10 px-1 py-0.5 text-[10px] text-black/40 dark:border-white/10 dark:text-white/40">
            filled in for you
          </span>
        )}
      </dd>
    </div>
  );
}

