const PLACEHOLDER_TITLE = "Kodely Site";
const EMPTY = { title:"", description:"", ogTitle:"", ogDescription:"", ogImage:"" };
function parseHead(html){
  if(!html || typeof DOMParser === "undefined") return EMPTY;
  const doc = new DOMParser().parseFromString(html, "text/html");
  const content = (s) => doc.querySelector(s)?.getAttribute("content")?.trim() ?? "";
  return {
    title: doc.querySelector("title")?.textContent?.trim() ?? "",
    description: content('meta[name="description"]'),
    ogTitle: content('meta[property="og:title"]'),
    ogDescription: content('meta[property="og:description"]'),
    ogImage: content('meta[property="og:image"]'),
  };
}
function servedValues(tags, projectName){
  const title = !tags.title || tags.title === PLACEHOLDER_TITLE ? projectName : tags.title;
  const generated = `${title} — built with Kodely.`;
  return { title, titleIsFallback: !tags.title || tags.title === PLACEHOLDER_TITLE,
    description: tags.description || generated, descriptionIsFallback: !tags.description,
    ogTitle: tags.ogTitle || title, ogTitleIsFallback: !tags.ogTitle,
    ogDescription: tags.ogDescription || generated, ogDescriptionIsFallback: !tags.ogDescription };
}
const foundation = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Kodely Site</title>
    <meta name="description" content="" />
    <meta property="og:title" content="" />
    <meta property="og:description" content="" />
    <meta property="og:type" content="website" />
    <meta name="twitter:card" content="summary_large_image" />
  </head>
  <body><div id="root"></div></body>
</html>`;
const agentWritten = `<!doctype html><html><head>
  <title>Bloom &amp; Co &#8212; Reformer studio</title>
  <meta content="Small-group reformer Pilates in Denver&#39;s Baker district." name="description">
  <meta property='og:title' content='Bloom &amp; Co'>
  <meta property="og:image" content="/og.png">
</head><body></body></html>`;
const out = {
  foundation: { parsed: parseHead(foundation), served: servedValues(parseHead(foundation), "Roan Coffee") },
  agent: { parsed: parseHead(agentWritten), served: servedValues(parseHead(agentWritten), "Bloom Pilates") },
  noHtml: parseHead(undefined),
};
JSON.stringify(out, null, 1)

