import { applySeo } from "file:///C:/Users/edmem/kodely-prod/lib/site-seo.ts";

const foundation = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Kodely Site</title>
    <meta name="description" content="" />
    <meta property="og:title" content="" />
    <meta property="og:description" content="" />
    <meta property="og:type" content="website" />
    <meta name="twitter:card" content="summary_large_image" />
  </head>
  <body><div id="root"></div></body>
</html>`;

const agentWritten = `<!doctype html><html><head>
  <title>Bloom &amp; Co &#8212; Reformer studio</title>
  <meta name="description" content="Small-group reformer Pilates in Denver&#39;s Baker district.">
  <meta property="og:title" content="Bloom &amp; Co">
  <meta property="og:image" content="/og.png">
</head><body></body></html>`;

const pick = (html) => {
  const grab = (re) => (html.match(re) || [, "(absent)"])[1];
  return {
    title: grab(/<title>([\s\S]*?)<\/title>/i),
    description: grab(/<meta\s+name="description"\s+content="([^"]*)"/i),
    ogTitle: grab(/<meta\s+property="og:title"\s+content="([^"]*)"/i),
    ogDescription: grab(/<meta\s+property="og:description"\s+content="([^"]*)"/i),
    ogImage: grab(/<meta\s+property="og:image"\s+content="([^"]*)"/i),
  };
};

console.log("FOUNDATION / project 'Roan Coffee':");
console.log(pick(applySeo(foundation, { projectName: "Roan Coffee", baseUrl: "https://roan.kodely.site" })));
console.log("\nAGENT-WRITTEN / project 'Bloom Pilates':");
console.log(pick(applySeo(agentWritten, { projectName: "Bloom Pilates", baseUrl: "https://bloom.kodely.site" })));

// Server-renders the two new editor components with the project's own React,
// so the markup/aria wiring can be asserted without a logged-in session.
const path = require("path");
const fs = require("fs");
const Module = require("module");

const ROOT = "C:/Users/edmem/kodely-prod";
const ts = require(path.join(ROOT, "node_modules/typescript"));
const React = require(path.join(ROOT, "node_modules/react"));
const { renderToStaticMarkup } = require(path.join(ROOT, "node_modules/react-dom/server"));

function load(file) {
  const src = fs.readFileSync(file, "utf8");
  const js = ts.transpileModule(src, {
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2022,
    },
  }).outputText;
  const m = new Module(file, null);
  m.filename = file;
  m.paths = Module._nodeModulePaths(path.dirname(file));
  m._compile(js, file);
  return m.exports;
}

// Minimal DOMParser stub: enough for parseHead's five querySelector calls.
class FakeDoc {
  constructor(map) {
    this.map = map;
  }
  querySelector(sel) {
    if (sel === "title") return this.map.title ? { textContent: this.map.title } : null;
    const m = sel.match(/\[(?:name|property)="([^"]+)"\]/);
    const v = m && this.map[m[1]];
    return v ? { getAttribute: () => v } : null;
  }
}
let PARSE_MAP = {};
globalThis.DOMParser = class {
  parseFromString() {
    return new FakeDoc(PARSE_MAP);
  }
};

const CostEstimate = load(path.join(ROOT, "app/projects/[id]/CostEstimate.tsx")).default;
const SeoPanel = load(path.join(ROOT, "app/projects/[id]/SeoPanel.tsx")).default;

const h = React.createElement;
const show = (label, el) => {
  console.log("\n===== " + label + " =====");
  console.log(renderToStaticMarkup(el).replace(/></g, ">\n<"));
};

show(
  "CostEstimate — new account, no history, create, 750 credits",
  h(CostEstimate, {
    id: "kodely-cost-estimate",
    kind: "create",
    range: { low: 120, high: 550 },
    balance: 750,
    avgBuildCredits: 400,
    measuredBuilds: 0,
  }),
);

show(
  "CostEstimate — no history, create, 300 credits (below top of range)",
  h(CostEstimate, {
    id: "kodely-cost-estimate",
    kind: "create",
    range: { low: 120, high: 550 },
    balance: 300,
    avgBuildCredits: 400,
    measuredBuilds: 0,
  }),
);

show(
  "CostEstimate — measured (4 builds, avg 210), edit, 150 credits",
  h(CostEstimate, {
    id: "kodely-cost-estimate",
    kind: "edit",
    range: { low: 60, high: 300 },
    balance: 150,
    avgBuildCredits: 210,
    measuredBuilds: 4,
  }),
);

show(
  "CostEstimate — 0 credits",
  h(CostEstimate, {
    id: "kodely-cost-estimate",
    kind: "edit",
    range: { low: 60, high: 300 },
    balance: 0,
    avgBuildCredits: 210,
    measuredBuilds: 4,
  }),
);

PARSE_MAP = {
  title: "Bloom & Co — Reformer studio",
  description: "Small-group reformer Pilates in Denver's Baker district.",
  "og:title": "Bloom & Co",
  "og:image": "/og.png",
};
show(
  "SeoPanel — agent-written head, published",
  h(SeoPanel, {
    projectId: "p1",
    projectName: "Bloom Pilates",
    published: true,
    liveUrl: "https://bloom.kodely.site",
    html: "<html><head></head></html>",
    onSaved: () => {},
  }),
);

PARSE_MAP = { title: "Kodely Site" };
show(
  "SeoPanel — untouched foundation head, unpublished",
  h(SeoPanel, {
    projectId: "p1",
    projectName: "Roan Coffee",
    published: false,
    liveUrl: null,
    html: "<html><head></head></html>",
    onSaved: () => {},
  }),
);

show(
  "SeoPanel — no index.html",
  h(SeoPanel, {
    projectId: "p1",
    projectName: "Roan Coffee",
    published: false,
    liveUrl: null,
    html: undefined,
    onSaved: () => {},
  }),
);

